// decodeProfile pulls a profileResponse out of a 200 response.
func decodeProfile(t *testing.T, resp *http.Response) profileResponse {
	t.Helper()
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("profile status = %d, want 200", resp.StatusCode)
	}
	var pr profileResponse
	if err := json.NewDecoder(resp.Body).Decode(&pr); err != nil {
		t.Fatalf("decode profileResponse: %v", err)
	}
	return pr
}

// mintDeviceToken pairs a real device through the real pairing flow and
// returns the raw bearer (the auth_chain_test mintDevice shape).
func mintDeviceToken(t *testing.T, devices *pairing.Service) string {
	t.Helper()
	ctx := context.Background()
	req, err := devices.CreateRequest(ctx, "10.0.0.1")
	if err != nil {
		t.Fatalf("CreateRequest: %v", err)
	}
	if _, err := devices.Approve(ctx, req.ID); err != nil {
		t.Fatalf("Approve: %v", err)
	}
	out, err := devices.Wait(ctx, req.ID)
	if err != nil || out.Token == "" {
		t.Fatalf("Wait: outcome=%+v err=%v (want the raw device token once)", out, err)
	}
	return out.Token
}

// TestProfileEndpoint pins the identity endpoints end to end over the REAL
// router (l6-accounts 8.1): the three kind shapes, the prefs roundtrip and
// whole-document replacement, the UserID-0 PUT refusal law, the malformed
// body 400, and the dangling-bound-device 404.
func TestProfileEndpoint(t *testing.T) {
	ctx := context.Background()

	t.Run("env_admin_shape", func(t *testing.T) {
		st := openAPIStore(t)
		h := authChainRouter(t, st, identity.NewService(st, nil))
		resp := doRequest(t, h, http.MethodGet, "/api/v1/profile", "", adminToken)
		defer resp.Body.Close()
		pr := decodeProfile(t, resp)
		if pr.Kind != "admin" {
			t.Fatalf("kind = %q, want admin", pr.Kind)
		}
		// No user_id on the wire at all (omitempty), fixed admin facts.
		raw, err := json.Marshal(pr)
		if err != nil {
			t.Fatalf("marshal: %v", err)
		}
		var wire map[string]any
		if err := json.Unmarshal(raw, &wire); err != nil {
			t.Fatalf("unmarshal wire: %v", err)
		}
		if _, ok := wire["user_id"]; ok {
			t.Fatalf("admin profile carries user_id: %s", raw)
		}
		if pr.Name != "admin" || pr.Role != "admin" {
			t.Fatalf("admin facts = {%q, %q}, want {admin, admin}", pr.Name, pr.Role)
		}
		if len(pr.Groups) != 0 {
			t.Fatalf("admin groups = %v, want empty", pr.Groups)
		}
		if string(pr.Prefs) != "{}" {
			t.Fatalf("admin prefs = %s, want {} (the empty override doc)", pr.Prefs)
		}
	})

	t.Run("user_session_shape", func(t *testing.T) {
		st := openAPIStore(t)
		ident := identity.NewService(st, nil)
		u, err := ident.Create(ctx, "alia", "pw")
		if err != nil {
			t.Fatalf("identity.Create: %v", err)
		}
		// The profile groups facts ride the REAL grant rows: two groups, the
		// names set the served order (UserGroups orders by name).
		if _, err := ident.CreateGroup(ctx, "Zeta"); err != nil {
			t.Fatalf("CreateGroup Zeta: %v", err)
		}
		if _, err := ident.CreateGroup(ctx, "Alpha"); err != nil {
			t.Fatalf("CreateGroup Alpha: %v", err)
		}
		if err := ident.AddUser(ctx, "Zeta", "alia"); err != nil {
			t.Fatalf("AddUser Zeta: %v", err)
		}
		if err := ident.AddUser(ctx, "Alpha", "alia"); err != nil {
			t.Fatalf("AddUser Alpha: %v", err)
		}
		sess, err := ident.MintSession(ctx, "alia", "pw")
		if err != nil {
			t.Fatalf("MintSession: %v", err)
		}
		h := authChainRouter(t, st, ident)

		resp := doRequest(t, h, http.MethodGet, "/api/v1/profile", "", sess.Token)
		defer resp.Body.Close()
		pr := decodeProfile(t, resp)
		if pr.Kind != "user" || pr.UserID != u.ID {
			t.Fatalf("profile = {kind %q, user_id %d}, want {user, %d}", pr.Kind, pr.UserID, u.ID)
		}
		// Create leaves the display name empty — the username serves.
		if pr.Name != "alia" {
			t.Fatalf("name = %q, want the username alia", pr.Name)
		}
		if pr.Role != "user" {
			t.Fatalf("role = %q, want the users.role literal user", pr.Role)
		}
		if len(pr.Groups) != 2 || pr.Groups[0].Name != "Alpha" || pr.Groups[1].Name != "Zeta" {
			t.Fatalf("groups = %+v, want [Alpha Zeta] in name order", pr.Groups)
		}
		if pr.Groups[0].ID == 0 || pr.Groups[0].ID == pr.Groups[1].ID {
			t.Fatalf("group ids not carried/distinct: %+v", pr.Groups)
		}
		if string(pr.Prefs) != "{}" {
			t.Fatalf("fresh prefs = %s, want the planted {}", pr.Prefs)
		}

		// An admin-role session stays kind:user with the users.role literal
		// (the role PROJECTS at the middleware — the profile serves the row's
		// role fact, not the projected principal constant).
		if err := ident.SetRole(ctx, "alia", "admin"); err != nil {
			t.Fatalf("SetRole: %v", err)
		}
		adminResp := doRequest(t, h, http.MethodGet, "/api/v1/profile", "", sess.Token)
		defer adminResp.Body.Close()
		adminPr := decodeProfile(t, adminResp)
		if adminPr.Kind != "user" || adminPr.Role != "admin" {
			t.Fatalf("admin-role session profile = {kind %q, role %q}, want {user, admin}",
				adminPr.Kind, adminPr.Role)
		}
	})

	t.Run("device_shapes", func(t *testing.T) {
		st := openAPIStore(t)
		ident := identity.NewService(st, nil)
		u, err := ident.Create(ctx, "vera", "pw")
		if err != nil {
			t.Fatalf("identity.Create: %v", err)
		}
		if _, err := ident.CreateGroup(ctx, "Scope"); err != nil {
			t.Fatalf("CreateGroup: %v", err)
		}
		if err := ident.AddUser(ctx, "Scope", "vera"); err != nil {
			t.Fatalf("AddUser: %v", err)
		}
		devices := pairing.NewService(st, nil)
		boundToken := mintDeviceToken(t, devices)
		// The admin bind endpoint is 9.3 — seed the exact row state the
		// middleware reads (the auth_chain_test shape).
		if _, err := st.DB().ExecContext(ctx,
			`UPDATE credentials SET user_id = ? WHERE token_hash = ?`,
			u.ID, hashBearerToken(boundToken)); err != nil {
			t.Fatalf("bind device credential: %v", err)
		}
		unboundToken := mintDeviceToken(t, devices)
		h := authChainRouter(t, st, ident)

		t.Run("unbound_device_shape", func(t *testing.T) {
			resp := doRequest(t, h, http.MethodGet, "/api/v1/profile", "", unboundToken)
			defer resp.Body.Close()
			pr := decodeProfile(t, resp)
			if pr.Kind != "device" {
				t.Fatalf("kind = %q, want device", pr.Kind)
			}
			raw, err := json.Marshal(pr)
			if err != nil {
				t.Fatalf("marshal: %v", err)
			}
			var wire map[string]any
			if err := json.Unmarshal(raw, &wire); err != nil {
				t.Fatalf("unmarshal wire: %v", err)
			}
			if _, ok := wire["user_id"]; ok {
				t.Fatalf("unbound device profile carries user_id: %s", raw)
			}
			if pr.Name != "device" || pr.Role != "client" {
				t.Fatalf("device facts = {%q, %q}, want {device, client}", pr.Name, pr.Role)
			}
			if len(pr.Groups) != 0 {
				t.Fatalf("device groups = %v, want empty", pr.Groups)
			}
			if string(pr.Prefs) != "null" {
				t.Fatalf("device prefs = %s, want null (no document exists)", pr.Prefs)
			}
		})

		t.Run("bound_device_serves_its_user_shape", func(t *testing.T) {
			resp := doRequest(t, h, http.MethodGet, "/api/v1/profile", "", boundToken)
			defer resp.Body.Close()
			pr := decodeProfile(t, resp)
			if pr.Kind != "user" || pr.UserID != u.ID {
				t.Fatalf("bound device profile = {kind %q, user_id %d}, want {user, %d}",
					pr.Kind, pr.UserID, u.ID)
			}
			if pr.Name != "vera" || pr.Role != "user" {
				t.Fatalf("bound device facts = {%q, %q}, want the user's {vera, user}", pr.Name, pr.Role)
			}
			if len(pr.Groups) != 1 || pr.Groups[0].Name != "Scope" {
				t.Fatalf("bound device groups = %+v, want the user's [Scope]", pr.Groups)
			}
		})

		t.Run("dangling_binding_404", func(t *testing.T) {
			// The device credential SURVIVES its user's delete (3.5's
			// documented cascade): the profile names an identity that no
			// longer exists — the repo's unknown-user convention, 404.
			// A second user absorbs the last-user guard so vera is deletable.
			if _, err := ident.Create(ctx, "spare", "pw"); err != nil {
				t.Fatalf("identity.Create spare: %v", err)
			}
			if err := ident.DeleteUser(ctx, "vera"); err != nil {
				t.Fatalf("DeleteUser: %v", err)
			}
			resp := doRequest(t, h, http.MethodGet, "/api/v1/profile", "", boundToken)
			defer resp.Body.Close()
			if resp.StatusCode != http.StatusNotFound {
				t.Fatalf("dangling binding = %d, want 404", resp.StatusCode)
			}
			if eb := decodeError(t, resp); eb.Error.Code != "not_found" {
				t.Fatalf("error code = %q, want not_found", eb.Error.Code)
			}
		})
	})

	t.Run("prefs_roundtrip", func(t *testing.T) {
		st := openAPIStore(t)
		ident := identity.NewService(st, nil)
		if _, err := ident.Create(ctx, "kai", "pw"); err != nil {
			t.Fatalf("identity.Create: %v", err)
		}
		sess, err := ident.MintSession(ctx, "kai", "pw")
		if err != nil {
			t.Fatalf("MintSession: %v", err)
		}
		h := authChainRouter(t, st, ident)

		// One PUT stores the doc verbatim and GET serves it back byte-for-byte.
		const doc = `{"auto_next":false}`
		resp := doRequest(t, h, http.MethodPut, "/api/v1/profile/prefs", doc, sess.Token)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusNoContent {
			t.Fatalf("prefs PUT = %d, want 204", resp.StatusCode)
		}
		pr := decodeProfile(t, doRequest(t, h, http.MethodGet, "/api/v1/profile", "", sess.Token))
		if !bytes.Equal(pr.Prefs, []byte(doc)) {
			t.Fatalf("served prefs = %s, want the stored %s verbatim", pr.Prefs, doc)
		}

		// A second PUT REPLACES the whole document — the first knob never
		// survives alongside the new one (never merged).
		const doc2 = `{"theme":"dark"}`
		resp2 := doRequest(t, h, http.MethodPut, "/api/v1/profile/prefs", doc2, sess.Token)
		defer resp2.Body.Close()
		if resp2.StatusCode != http.StatusNoContent {
			t.Fatalf("second prefs PUT = %d, want 204", resp2.StatusCode)
		}
		pr2 := decodeProfile(t, doRequest(t, h, http.MethodGet, "/api/v1/profile", "", sess.Token))
		if !bytes.Equal(pr2.Prefs, []byte(doc2)) {
			t.Fatalf("replaced prefs = %s, want exactly %s (no merge)", pr2.Prefs, doc2)
		}

		// Per-user isolation is identity's row keying, pinned at the seam:
		// another user's profile never sees kai's document (it carries the
		// planted {} — the env defaults answer for untouched knobs).
		if _, err := ident.Create(ctx, "noor", "pw"); err != nil {
			t.Fatalf("identity.Create noor: %v", err)
		}
		noorSess, err := ident.MintSession(ctx, "noor", "pw")
		if err != nil {
			t.Fatalf("MintSession noor: %v", err)
		}
		noorPr := decodeProfile(t, doRequest(t, h, http.MethodGet, "/api/v1/profile", "", noorSess.Token))
		if string(noorPr.Prefs) != "{}" {
			t.Fatalf("untouched user prefs = %s, want {}", noorPr.Prefs)
		}
	})

	t.Run("put_refusals", func(t *testing.T) {
		st := openAPIStore(t)
		ident := identity.NewService(st, nil)
		if _, err := ident.Create(ctx, "zara", "pw"); err != nil {
			t.Fatalf("identity.Create: %v", err)
		}
		devices := pairing.NewService(st, nil)
		deviceToken := mintDeviceToken(t, devices)
		h := authChainRouter(t, st, ident)

		// Env admin: no per-user document behind the token — 409.
		adminResp := doRequest(t, h, http.MethodPut, "/api/v1/profile/prefs", `{"a":1}`, adminToken)
		defer adminResp.Body.Close()
		if adminResp.StatusCode != http.StatusConflict {
			t.Fatalf("env-admin prefs PUT = %d, want 409", adminResp.StatusCode)
		}
		if eb := decodeError(t, adminResp); eb.Error.Code != "conflict" {
			t.Fatalf("env-admin error code = %q, want conflict", eb.Error.Code)
		}

		// Unbound device: same law (UserID 0 — no document behind it).
		devResp := doRequest(t, h, http.MethodPut, "/api/v1/profile/prefs", `{"a":1}`, deviceToken)
		defer devResp.Body.Close()
		if devResp.StatusCode != http.StatusConflict {
			t.Fatalf("device prefs PUT = %d, want 409", devResp.StatusCode)
		}
		if eb := decodeError(t, devResp); eb.Error.Code != "conflict" {
			t.Fatalf("device error code = %q, want conflict", eb.Error.Code)
		}

		// Malformed bodies from a user-backed principal: not JSON, and JSON
		// that is not an object, both 400.
		sess, err := ident.MintSession(ctx, "zara", "pw")
		if err != nil {
			t.Fatalf("MintSession: %v", err)
		}
		for _, bad := range []string{`{"a":`, `[1,2]`, `null`, `"str"`} {
			resp := doRequest(t, h, http.MethodPut, "/api/v1/profile/prefs", bad, sess.Token)
			code := resp.StatusCode
			resp.Body.Close()
			if code != http.StatusBadRequest {
				t.Fatalf("prefs PUT body %q = %d, want 400", bad, code)
			}
		}
		eb := decodeError(t, doRequest(t, h, http.MethodPut, "/api/v1/profile/prefs", `{"a":`, sess.Token))
		if eb.Error.Code != "bad_request" {
			t.Fatalf("error code = %q, want bad_request", eb.Error.Code)
		}
	})
}
